{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Chloramphenicol, which shares the p-nitrophenyl motif, has oral bioavailability greater than 100% relative to the succinate prodrug in children, demonstrating that a p-nitrophenyl-containing polar drug can be essentially completely absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Chloramphenicol palmitate, another p-nitrophenyl analogue, has absolute oral bioavailability of 85 ± 15% in children, supporting high oral absorption for this nitroaromatic structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A chromone/coumarin-containing analogue (Z18483535) has human oral bioavailability of 55.7%, directly supporting that the query's coumarin core can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Roquinimex, a 4-hydroxy-2-oxo heterocycle with an acidic enol/phenol system similar to the 4-hydroxycoumarin scaffold, has complete oral bioavailability in healthy volunteers, supporting high absorption for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Lercanidipine, a nitrophenyl dihydropyridine, has only about 10% absolute bioavailability in fed patients due to extensive first-pass metabolism; this is contradictory evidence, but its dihydropyridine scaffold and metabolic liability are not closely transferable to the 4-hydroxycoumarin query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The most transferable experimental evidence supports high oral bioavailability: p-nitrophenyl-containing drugs (chloramphenicol, chloramphenicol palmitate) and 4-hydroxy heterocycle/coumarin-like molecules (roquinimex, Z18483535) show F ≥55% or complete absorption. Low-F analogues are structurally distant dihydropyridines, an organophosphate, and a nitrate ester whose first-pass liabilities do not transfer strongly to the warfarin-like 4-hydroxycoumarin scaffold. Therefore the query is predicted to have F ≥20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query or its closest warfarin analogue; all evidence molecules have Morgan similarity ≤0.30.",
    "No data specifically address how the 4-nitro substituent alters coumarin permeability, transporter efflux, or first-pass metabolism.",
    "The physicochemical prior is mixed/unclear and cannot independently resolve the prediction."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C31", "C35"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "p-nitrophenyl antibiotics"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C11"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "coumarin/chromone analogue"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C10", "C23"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "4-hydroxy heterocycle"
    },
    {
      "applicability": "low",
      "card_ids": ["C16", "C18", "C13", "C22", "C28", "C03"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "dihydropyridine calcium antagonists"
    },
    {
      "applicability": "not_applicable",
      "card_ids": ["C05", "C02"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "organophosphate/nitrate ester prodrugs"
    }
  ],
  "revision_action": "initial"
}

